import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { exportCsv } from '../src/export.js';

test('exportCsv returns CSV string with header', () => {
  const result = exportCsv([]);
  assert.ok(result.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv header ends with newline', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.ok(lines.length >= 2);
});

test('exportCsv with empty invoice list returns only header', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv includes draft invoice with empty number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
  }).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.ok(lines[1].includes('draft'));
});

test('exportCsv formats amounts as euros with 2 decimals', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  assert.ok(result.includes('.'));
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5].substring(fields[5].length - 2), '.00');
});

test('exportCsv includes customer name', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('Northwind Studio'));
});

test('exportCsv escapes commas in customer names', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-004',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('Smith, Jones & Partners'));
  assert.ok(lines[1].includes('"'));
});

test('exportCsv escapes quotes in customer names', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-006',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('""'));
});

test('exportCsv includes invoice status', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('issued'));
});

test('exportCsv includes invoice number for issued invoices', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('INV-2026-0001'));
});

test('exportCsv includes dates', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('2026-10-01'));
  assert.ok(lines[1].includes('2026-10-15'));
});

test('exportCsv includes subtotal, discount, vat, total, and due', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields.length, 10);
  assert.ok(!isNaN(parseFloat(fields[5])));
  assert.ok(!isNaN(parseFloat(fields[6])));
  assert.ok(!isNaN(parseFloat(fields[7])));
  assert.ok(!isNaN(parseFloat(fields[8])));
  assert.ok(!isNaN(parseFloat(fields[9])));
});

test('exportCsv handles paid invoices with due = 0', () => {
  const invoice = recordPayment(
    recordPayment(
      issueInvoice(
        createInvoice({
          customerId: 'C-001',
          issueDate: '2026-10-01',
          lines: [{ sku: 'STICKER', qty: 5 }],
        }).value,
        [],
      ).value,
      { amount: 144, date: '2026-10-02' },
    ).value,
    { amount: 144, date: '2026-10-03' },
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('0.00'));
  assert.ok(lines[1].includes('paid'));
});

test('exportCsv handles partially paid invoices', () => {
  const invoice = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-01',
        lines: [{ sku: 'STICKER', qty: 5 }],
      }).value,
      [],
    ).value,
    { amount: 100, date: '2026-10-02' },
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('partially_paid'));
});

test('exportCsv preserves invoice order', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-02',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [inv1.number],
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-03',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [inv1.number, inv2.number],
  ).value;

  const result = exportCsv([inv3, inv1, inv2]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('INV-2026-0003'));
  assert.ok(lines[2].includes('INV-2026-0001'));
  assert.ok(lines[3].includes('INV-2026-0002'));
});

test('exportCsv ends with newline', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  assert.ok(result.endsWith('\n'));
});

test('exportCsv handles unknown customer gracefully', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
  }).value;

  const badInvoice = { ...invoice, customerId: 'UNKNOWN' };

  const result = exportCsv([badInvoice]);
  const lines = result.split('\n');
  assert.ok(lines[1]);
});

test('exportCsv with multiple invoices includes all', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-02',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [inv1.number],
  ).value;

  const result = exportCsv([inv1, inv2]);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
});

test('exportCsv amounts do not include currency sign', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  assert.ok(!result.includes('€'));
});

test('exportCsv amounts do not include thousands separator', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'LOGO-PACK', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  const amounts = [fields[5], fields[6], fields[7], fields[8], fields[9]];
  for (const amount of amounts) {
    if (amount && !amount.includes('"')) {
      assert.ok(!amount.includes(','), `Amount ${amount} contains comma`);
    }
  }
});

test('exportCsv correctly calculates CSV line count', () => {
  const invoices = [];
  for (let i = 0; i < 5; i++) {
    invoices.push(
      issueInvoice(
        createInvoice({
          customerId: 'C-001',
          issueDate: '2026-10-01',
          lines: [{ sku: 'STICKER', qty: 5 }],
        }).value,
        invoices.map(inv => inv.number).filter(n => n),
      ).value,
    );
  }

  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 7);
});
